/// <summary>
/// MPJ_21275_BackOrders
/// Extension of SalesTable form datasource of SalesLine
/// </summary>
[ExtensionOf(formDataSourceStr(SalesTable, SalesLine))]
final class METSalesTableFormSalesLineDS_Extension
{
}

Method.Source:
    /// <summary>
    /// MPJ_21275_BackOrders
    /// Based up on the SO header, Item master and Site Allow back orders check box Sales line will be activated
    /// </summary>
    /// <returns>current record</returns>
    public int active()
    {
        SalesLine           salesLine           =  this.formRun().dataSource(formDataSourceStr(SalesTable, SalesLine)).cursor(); 
        SalesLine           salesLineBackOrder  = SalesLine::findRecId(salesLine.RecId, true);
        METInventTable      metInventTable;
        InventDim           inventDim;
        InventSite          inventSite;
        SalesTable          salesTable;
        FormCheckBoxControl metAllowBackOrdersLine = this.formRun().design().controlName(formControlStr(SalesTable, METAllowBackOrdersLine)) as FormCheckBoxControl;
        metInventTable      = METInventTable::find(salesLine.ItemId);
        inventDim           = InventDim::find(salesLine.InventDimId);
        inventSite          = InventSite::find(inventDim.InventSiteId);
        
        select firstonly1 METAllowBackOrders from salesTable
            where salesTable.SalesId == salesLine.SalesId;

        ttsbegin;
        if (metInventTable.AllowBackOrders == NoYes::Yes && inventSite.METAllowBackOrders == NoYes::Yes && salesTable.METAllowBackOrders == NoYes::Yes)
        {
            
            salesLineBackOrder.METAllowBackOrders = NoYes::Yes;
            salesLineBackOrder.update();
            metAllowBackOrdersLine.allowEdit(true);
        }
        else if (metInventTable.AllowBackOrders == NoYes::No || inventSite.METAllowBackOrders == NoYes::No || salesTable.METAllowBackOrders == NoYes::No)
        {
            salesLineBackOrder.METAllowBackOrders = NoYes::No;
            salesLineBackOrder.update();
            metAllowBackOrdersLine.allowEdit(false);
        }
        ttscommit;

        salesLine.reread();
        return next active();
    }
